test('resolveBrickCollision: top hit flips vy and pushes out', () => {
  const ball = { x: 100, y: 100, r: 7, vx: 0, vy: UP };
  const brick = { x: 80, y: 90, w: 40, h: 20 };
  // Ball is overlapping the bottom of the brick (ball.y + r = 107, brick.y = 90... wait)
  // If ball is at 100, r=7, then bottom is 107. Brick is at 90, h=20, bottom is 110.
  // So ball is inside the brick.
  // We want a top hit: ball hits the bottom edge of the brick.
  // Brick: y=90, h=20. Bottom edge is y=110.
  // Ball: y=112, r=7. Top edge is y=105. Overlap is 5px.
  const ballTop = { x: 100, y: 112, r: 7, vx: 0, vy: UP };
  resolveBrickCollision(ballTop, brick);
  assert.equal(ballTop.vy, DOWN);
  assert.ok(ballTop.y >= 110 + 7, 'ball should be pushed below the brick');
});

test('resolveBrickCollision: bottom hit flips vy and pushes out', () => {
  const ball = { x: 100, y: 88, r: 7, vx: 0, vy: DOWN };
  const brick = { x: 80, y: 90, w: 40, h: 20 };
  // Ball top edge at 81, bottom at 95. Brick top edge at 90.
  resolveBrickCollision(ball, brick);
  assert.equal(ball.vy, UP);
  assert.ok(ball.y <= 90 - 7, 'ball should be pushed above the brick');
});

test('resolveBrickCollision: left hit flips vx and pushes out', () => {
  const ball = { x: 78, y: 100, r: 7, vx: RIGHT, vy: 0 };
  const brick = { x: 80, y: 90, w: 40, h: 20 };
  // Ball right edge at 85. Brick left edge at 80.
  resolveBrickCollision(ball, brick);
  assert.equal(ball.vx, LEFT);
  assert.ok(ball.x <= 80 - 7, 'ball should be pushed left of the brick');
});

test('resolveBrickCollision: right hit flips vx and pushes out', () => {
  const ball = { x: 122, y: 100, r: 7, vx: LEFT, vy: 0 };
  const brick = { x: 80, y: 90, w: 40, h: 20 };
  // Ball left edge at 115. Brick right edge at 120.
  resolveBrickCollision(ball, brick);
  assert.equal(ball.vx, RIGHT);
  assert.ok(ball.x >= 120 + 7, 'ball should be pushed right of the brick');
});

test('resolveBrickCollision: corner hit flips both', () => {
  const ball = { x: 78, y: 112, r: 7, vx: RIGHT, vy: UP };
  const brick = { x: 80, y: 90, w: 40, h: 20 };
  // Overlap X: ball.x+r=85, brick.x=80 => 5px
  // Overlap Y: ball.y-r=105, brick.y+h=110 => 5px
  // Corner hit: equal overlap.
  resolveBrickCollision(ball, brick);
  assert.equal(ball.vx, LEFT);
  assert.equal(ball.vy, DOWN);
});

